mapper.select:
select max(windturbine)
from hm_realtime
where windfarm = #{windfarmId};

select *
from (
    select *
    from hm_realtime
    where windfarm = #{windfarm}
    order by id desc limit #{N}
    ) tempTable
order by gmt_received;

select *
from (
    select *
    from hm_realtime
    where windfarm = #{windfarm} and status = #{status}
    order by id desc limit #{N}
    ) tempTable
order by gmt_received;

SELECT * FROM hm_realtime
WHERE 1=1

    AND windfarm = #{windfarm}


    AND windturbine = #{windturbine}


    AND status = #{status}


    AND gmt_received >= #{startTime}


    AND gmt_received <= #{endTime}

ORDER BY gmt_received DESC

    LIMIT #{limit}
